@Override
        public void tick() {
            this.mob.getLookControl().setLookAt(Vec3.atCenterOf(this.path.getTarget()));
            if (this.mob.horizontalCollision && this.mob.onGround) {
                this.mob.jumpFromGround();
            }
            if (this.mob.level.getGameRules().getBoolean(GameRules.RULE_MOBGRIEFING)) {
                AABB boundingBox = this.mob.getBoundingBox().inflate(0.2);
                for (BlockPos pos : BlockPos.betweenClosed(Mth.floor(boundingBox.minX), Mth.floor(boundingBox.minY), Mth.floor(boundingBox.minZ), Mth.floor(boundingBox.maxX), Mth.floor(boundingBox.maxY), Mth.floor(boundingBox.maxZ))) {
                    BlockState state = this.mob.level.getBlockState(pos);
                    if (!state.is(NaturalistTags.BlockTags.RHINO_CHARGE_BREAKABLE)) continue;
                    this.mob.level.destroyBlock(pos, true, this.mob);
                }
            }
            if (!this.mob.level.isClientSide()) {
                ((ServerLevel) this.mob.level).sendParticles(ParticleTypes.CAMPFIRE_COSY_SMOKE, this.mob.getX(), this.mob.getY(), this.mob.getZ(), 5, this.mob.getBbWidth() / 4.0F, 0, this.mob.getBbWidth() / 4.0F, 0.01D);
            }
            if (this.mob.level.getGameTime() % 2L == 0L) {
                this.mob.playSound(SoundEvents.HOGLIN_STEP, 0.5F, this.mob.getVoicePitch());
            }
            this.tryToHurt();
        }

@Override
        public boolean canUse() {
            LivingEntity target = this.mob.getTarget();
            if (target == null || !target.isAlive() || this.mob.hasChargeCooldown() || this.mob.stunnedTick > 0) {
                return false;
            }
            this.path = this.mob.getNavigation().createPath(target, 0);
            return target instanceof Player && this.path != null;
        }

@Override
        public boolean canContinueToUse() {
            LivingEntity target = this.mob.getTarget();
            if (target == null || !target.isAlive() || this.mob.hasChargeCooldown() || this.mob.stunnedTick > 0) {
                return false;
            }
            return !this.mob.getNavigation().isDone();
        }

@Override
        public void start() {
            BlockPos blockPosition = this.mob.blockPosition();
            BlockPos target = this.path.getTarget();
            this.chargeDirection = new Vec3(blockPosition.getX() - target.getX(), 0.0, blockPosition.getZ() - target.getZ()).normalize();
            this.mob.getNavigation().moveTo(this.path, this.speedModifier);
            this.mob.setAggressive(true);
        }

@Override
        public void stop() {
            this.mob.resetChargeCooldownTicks();
            this.mob.getNavigation().stop();
        }

protected void tryToHurt() {
            List<LivingEntity> nearbyEntities = this.mob.level.getNearbyEntities(LivingEntity.class, TargetingConditions.forCombat(), this.mob, this.mob.getBoundingBox());
            if (!nearbyEntities.isEmpty()) {
                LivingEntity livingEntity = nearbyEntities.get(0);
                if (!(livingEntity instanceof Rhino)) {
                    livingEntity.hurt(DamageSource.mobAttack(this.mob), (float) this.mob.getAttributeValue(Attributes.ATTACK_DAMAGE));
                    float speed = Mth.clamp(this.mob.getSpeed() * 1.65f, 0.2f, 3.0f);
                    float shieldBlockModifier = livingEntity.isDamageSourceBlocked(DamageSource.mobAttack(this.mob)) ? 0.5f : 1.0f;
                    livingEntity.knockback(shieldBlockModifier * speed * 2.0D, this.chargeDirection.x(), this.chargeDirection.z());
                    double knockbackResistance = Math.max(0.0, 1.0 - livingEntity.getAttributeValue(Attributes.KNOCKBACK_RESISTANCE));
                    livingEntity.setDeltaMovement(livingEntity.getDeltaMovement().add(0.0, 0.4f * knockbackResistance, 0.0));
                    this.mob.swing(InteractionHand.MAIN_HAND);
                    if (livingEntity.equals(this.mob.getTarget())) {
                        this.stop();
                    }
                }
            }
        }

@Override
    public void tick() {
        super.tick();
        if (level == null || level.isClientSide())
            return;
        if (craftCooldown > 0) {
            craftCooldown--;
            return;
        }

        if (!hasSource && level.getGameTime() % 5 == 0 && SourceUtil.takeSourceMultipleWithParticles(worldPosition, level, 6, 50) != null) {
            this.hasSource = true;
            level.setBlockAndUpdate(worldPosition, level.getBlockState(worldPosition).setValue(WixieCauldron.FILLED, true));
            setChanged();
        }

        if (!hasSource) return;

        if (!level.isClientSide() && level.getGameTime() % 20 == 0) {
            if (craftManager.isCraftCompleted()) {
                rotateCraft();
            }
        }
    }

public void rotateCraft() {
        BlockPos leftBound = worldPosition.below().south().east();
        BlockPos rightBound = worldPosition.above().north().west();
        List<ItemStack> itemStacks = new ArrayList<>();
        for (BlockPos pos : BlockPos.betweenClosed(leftBound, rightBound)) {
            if (level.getBlockEntity(pos) instanceof ArcanePedestalTile pedestalTile
                    && !pedestalTile.getStack().isEmpty()
                    && !pedestalTile.hasSignal) {
                itemStacks.add(pedestalTile.getStack().copy());
            }
        }
        if (itemStacks.isEmpty())
            return;
        // Get the next recipe to craft
        if (this.craftingIndex >= itemStacks.size()) {
            this.craftingIndex = 0;
        }
        ItemStack nextStack = itemStacks.get(this.craftingIndex);
        MultiRecipeWrapper recipeWrapper = getRecipesForStack(nextStack);
        craftingIndex++;
        if (recipeWrapper == null || recipeWrapper.isEmpty()) {
            return;
        }
        Map<Item, Integer> count = getInventoryCount();

        IRecipeWrapper.InstructionsForRecipe instructions = recipeWrapper.canCraft(count, level, worldPosition);
        if (instructions == null)
            return;
        if (!recipeWrapper.isEmpty() && instructions.recipe().recipeIngredients.get(0).getCustomIngredient() instanceof DataComponentIngredient custom) {
            Ingredient itemIngred = instructions.recipe().recipeIngredients.get(1);
            List<ItemStack> needed = new ArrayList<>(Arrays.asList(itemIngred.getItems()));
            if(needed.isEmpty()){
                return;
            }
            PotionContents potionNeeded = custom.getItems().toList().get(0).get(DataComponents.POTION_CONTENTS);
            PotionContents potionOutput = PotionUtil.getContents(instructions.recipe().outputStack);
            if(potionNeeded == null){
                return;
            }
            boolean foundInput = potionNeeded.is(Potions.WATER) || findNeededPotion(potionNeeded, 300, level, worldPosition) != null;
            boolean foundRoomForOutput = findPotionStorage(level, worldPosition, potionOutput) != null;
            if (!foundRoomForOutput || !foundInput) {
                return;
            }
            craftManager = new PotionCraftingManager(potionNeeded, needed, potionOutput);
            //BrewingRecipe
        } else {
            craftManager = new CraftingManager(instructions.recipe().outputStack.copy(), instructions.itemsNeeded());
        }
        onCraftStart();
        level.sendBlockUpdated(worldPosition, level.getBlockState(worldPosition), level.getBlockState(worldPosition), 3);
        stackBeingCrafted = nextStack.copy();
        updateBlock();
    }

public void attemptFinish() {
        if (!craftManager.canBeCompleted() || craftManager.isCraftCompleted())
            return;
        craftManager.completeCraft(this);
        this.craftCooldown = 1;
        this.stackBeingCrafted = ItemStack.EMPTY;
        craftManager.outputStack = ItemStack.EMPTY;
        updateBlock();
    }

public boolean canBeCompleted() {
        return !isCraftInvalid() && neededItems.isEmpty();
    }

public boolean isCraftCompleted() {
        return isCraftInvalid() || craftCompleted;
    }

public boolean isCraftInvalid() {
        return outputStack.isEmpty();
    }

public void completeCraft(WixieCauldronTile tile) {
        Level level = tile.getLevel();
        BlockPos worldPosition = tile.getBlockPos();

        if (!outputStack.isEmpty()) {
            level.addFreshEntity(new ItemEntity(level, worldPosition.getX(), worldPosition.getY() + 1.0, worldPosition.getZ(), outputStack.copy()));
        }
        for (ItemStack i : remainingItems) {
            if (!i.isEmpty()) {
                level.addFreshEntity(new ItemEntity(level, worldPosition.getX(), worldPosition.getY() + 1.0, worldPosition.getZ(), i.copy()));
            }
        }
        tile.hasSource = false;
        tile.onCraftingComplete();
        this.craftCompleted = true;
    }

public void read(HolderLookup.Provider provider, CompoundTag tag) {
        outputStack = ItemStack.parseOptional(provider, tag.getCompound("output_stack"));
        neededItems = NBTUtil.readItems(provider, tag, "progress");
        remainingItems = NBTUtil.readItems(provider, tag, "refund");
    }

public void write(HolderLookup.Provider provider, CompoundTag tag) {
        Tag stack = outputStack.saveOptional(provider);
        tag.put("output_stack", stack);

        NBTUtil.writeItems(provider, tag, "progress", neededItems);
        NBTUtil.writeItems(provider, tag, "refund", remainingItems);
        tag.putBoolean("completed", craftCompleted);
    }

@Override
    public void completeCraft(WixieCauldronTile tile) {
        Level level = tile.getLevel();
        BlockPos worldPosition = tile.getBlockPos();
        BlockPos jarPos = WixieCauldronTile.findPotionStorage(tile.getLevel(), tile.getBlockPos(), potionOut);
        if (jarPos == null) {
            if (!tile.needsPotionStorage()) {
                tile.setNeedsPotionStorage(true);
                level.sendBlockUpdated(worldPosition, level.getBlockState(worldPosition), level.getBlockState(worldPosition), 3);
            }
            return;
        } else if (level instanceof ServerLevel serverLevel && level.getBlockEntity(jarPos) instanceof PotionJarTile jar) {
            tile.setNeedsPotionStorage(false);
            jar.add(potionOut, 300);
            ParticleColor color2 = ParticleColor.fromInt(jar.getColor());
            EntityFlyingItem.spawn(serverLevel, new Vec3(worldPosition.getX() + 0.5, worldPosition.getY() + 1.0, worldPosition.getZ() + 0.5),
                            new Vec3(jarPos.getX() + 0.5, jarPos.getY(), jarPos.getZ() + 0.5),
                            Math.round(255 * color2.getRed()), Math.round(255 * color2.getGreen()), Math.round(255 * color2.getBlue()))
                    .withNoTouch();
        }
        super.completeCraft(tile);
    }

@Override
    public void tick() {
        if (recheckInventoryCooldown < 0) {
            recheckInventoryCooldown = 15;
            if (!hasStealableInventory(target)) {
                target = null;
                return;
            }
        }
        if (target != null) {
            gingerbreadMan.lookAt(EntityAnchorArgument.Anchor.EYES, target.getEyePosition());
            double dist = gingerbreadMan.distanceTo(target);
            if (dist < target.getBbWidth() + 1.0D && gingerbreadMan.hasLineOfSight(target)) {
                if(gingerbreadMan.getAnimation() == IAnimatedEntity.NO_ANIMATION || gingerbreadMan.getAnimation() == null){
                    gingerbreadMan.setAnimation(gingerbreadMan.getAnimationForHand(false));
                }
                if(gingerbreadMan.getAnimation() == gingerbreadMan.getAnimationForHand(false) && gingerbreadMan.getAnimationTick() == 8){
                    ItemStack stolenItem = stealOneFrom(target);
                    hasStolen = true;
                    gingerbreadMan.setItemInHand(InteractionHand.OFF_HAND, stolenItem);
                    gingerbreadMan.setCarryingItem(true);
                    gingerbreadMan.fleeFromFor(target, 120 + gingerbreadMan.getRandom().nextInt(60));
                }
            } else {
                gingerbreadMan.getNavigation().moveTo(target, 1.0D);
            }
        }
    }

@Override
    public boolean canUse() {
        if(gingerbreadMan.isOvenSpawned()){
            return false;
        }
        if (executionCooldown > 0) {
            executionCooldown--;
            return false;
        } else if (gingerbreadMan.getItemInHand(InteractionHand.OFF_HAND).isEmpty() && gingerbreadMan.getRandom().nextInt(60) == 0) {
            executionCooldown = 120 + gingerbreadMan.getRandom().nextInt(120);
            Entity newTarget = findStealTarget();
            if (newTarget != null && newTarget.isAlive() && canStealFromEntityType(newTarget)) {
                target = newTarget;
                return true;
            }
        }
        return false;
    }

@Override
    public boolean canContinueToUse() {
        return !hasStolen && (target != null && target.isAlive()) && canStealFromEntityType(target);
    }

@Override
    public void start() {
        hasStolen = false;
    }

@Nullable
    public Entity findStealTarget() {
        List<Entity> list = gingerbreadMan.level().getEntities(gingerbreadMan, gingerbreadMan.getBoundingBox().inflate(20.0D), GingerbreadManStealGoal::hasStealableInventory);
        if(list.isEmpty()){
            Player nearest = gingerbreadMan.level().getNearestPlayer(gingerbreadMan, 20.0D);
            if(nearest != null && hasStealableInventory(nearest)){
                return nearest;
            }
            return null;
        }else{
            return Util.getRandom(list, gingerbreadMan.getRandom());
        }
    }

public static boolean hasStealableInventory(Entity entity) {
        if(!canStealFromEntityType(entity)){
            return false;
        }
        LazyOptional<IItemHandler> lazyOptional = entity.getCapability(ForgeCapabilities.ITEM_HANDLER, Direction.DOWN);
        if (lazyOptional.isPresent()) {
            IItemHandler handler = lazyOptional.orElse(null);
            for (int i = 0; i < handler.getSlots(); i++) {
                if (handler.getStackInSlot(i).is(ACTagRegistry.GINGERBREAD_MAN_STEALS)) {
                    return true;
                }
            }
        }
        return false;
    }

private static boolean canStealFromEntityType(Entity entity){
        if(entity instanceof Player player && player.isCreative()){
            return false;
        }
        return !(entity instanceof GingerbreadManEntity);
    }

public ItemStack stealOneFrom(Entity entity) {
        LazyOptional<IItemHandler> lazyOptional = entity.getCapability(ForgeCapabilities.ITEM_HANDLER, Direction.DOWN);
        if (lazyOptional.isPresent()) {
            IItemHandler handler = lazyOptional.orElse(null);
            List<Integer> validSlots = new ArrayList<>();
            for (int i = 0; i < handler.getSlots(); i++) {
                if (handler.getStackInSlot(i).is(ACTagRegistry.GINGERBREAD_MAN_STEALS)) {
                    validSlots.add(i);
                }
            }
            if (!validSlots.isEmpty()) {
                int slotId = Util.getRandom(validSlots, gingerbreadMan.getRandom());
                ItemStack stack = handler.getStackInSlot(slotId);
                ItemStack copy = stack.copy();
                copy.setCount(1);
                if (stack.is(ACTagRegistry.GINGERBREAD_MAN_STEALS)) {
                    stack.shrink(1);
                }
                return copy;
            }
        }
        return ItemStack.EMPTY;
    }

@Override
    public void tick() {
        super.tick();
        BlockPos target = getMoveToTarget();
        if (target != null) {
            if (isReachedTarget()) {
                if (relicheirus.lockTreePosition(blockPos)) {
                    if (relicheirus.getAnimation() == IAnimatedEntity.NO_ANIMATION) {
                        relicheirus.setPeckY(blockPos.getY());
                        relicheirus.setAnimation(RelicheirusEntity.ANIMATION_PUSH_TREE);
                    } else if (relicheirus.getAnimation() == RelicheirusEntity.ANIMATION_PUSH_TREE) {
                        if (relicheirus.getAnimationTick() >= 35 && !madeTreeEntity) {
                            madeTreeEntity = true;
                            relicheirus.playSound(ACSoundRegistry.RELICHEIRUS_TOPPLE.get());
                            List<BlockPos> gathered = new ArrayList<>();
                            gatherAttachedBlocks(blockPos, blockPos, gathered);
                            if (!gathered.isEmpty()) {
                                List<MovingBlockData> allData = new ArrayList<>();
                                for (BlockPos pos : gathered) {
                                    BlockState moveState = relicheirus.level().getBlockState(pos);
                                    BlockEntity te = relicheirus.level().getBlockEntity(pos);
                                    BlockPos offset = pos.subtract(blockPos);
                                    MovingBlockData data = new MovingBlockData(moveState, moveState.getShape(relicheirus.level(), pos), offset, te == null ? null : te.saveWithoutMetadata());
                                    relicheirus.level().removeBlockEntity(pos);
                                    allData.add(data);
                                }
                                for (BlockPos pos : gathered) {
                                    relicheirus.level().setBlock(pos, Blocks.AIR.defaultBlockState(), 3);
                                }
                                FallingTreeBlockEntity fallingTree = ACEntityRegistry.FALLING_TREE_BLOCK.get().create(relicheirus.level());
                                fallingTree.moveTo(Vec3.atCenterOf(blockPos));
                                fallingTree.setAllBlockData(FallingTreeBlockEntity.createTagFromData(allData));
                                fallingTree.setPlacementCooldown(1);
                                Vec3 vec3 = Vec3.atCenterOf(blockPos).subtract(relicheirus.position());
                                float f = -((float) Mth.atan2(vec3.x, vec3.z)) * 180.0F / (float) Math.PI;
                                fallingTree.setFallDirection(Direction.fromYRot(f));
                                relicheirus.level().addFreshEntity(fallingTree);
                            }
                        }
                    }
                }
            } else {
                if (relicheirus.getNavigation().isDone()) {
                    Vec3 vec31 = Vec3.atCenterOf(target);
                    Vec3 vec32 = vec31.subtract(relicheirus.position());
                    if (vec32.length() > 1) {
                        vec32 = vec32.normalize();
                    }
                    Vec3 delta = new Vec3(vec32.x * 0.1F, 0F, vec32.z * 0.1F);
                    relicheirus.setDeltaMovement(relicheirus.getDeltaMovement().add(delta));
                }
            }
        }
    }

public boolean canUse() {
        return relicheirus.getPushingTreesFor() > 0 && !relicheirus.isBaby() && super.canUse();
    }

public boolean canContinueToUse() {
        return super.canContinueToUse() && !madeTreeEntity;
