public void stop() {
        this.blockPos = BlockPos.ZERO;
        madeTreeEntity = false;
        super.stop();
    }

public void gatherAttachedBlocks(BlockPos origin, BlockPos pos, List<BlockPos> list) {
        if (list.size() < MAXIMUM_BLOCKS_PUSHED) {
            if (!list.contains(pos)) {
                list.add(pos);
                for (BlockPos blockpos1 : BlockPos.betweenClosed(pos.offset(-1, -1, -1), pos.offset(1, 1, 1))) {
                    if (!blockpos1.equals(pos) && pos.distToCenterSqr(origin.getX(), pos.getY(), origin.getZ()) < MAX_TREE_SPREAD) {
                        if (isTreePart(blockpos1)) {
                            gatherAttachedBlocks(origin, blockpos1.immutable(), list);
                        }
                    }
                }
            }

        }
    }

public boolean isTreePart(BlockPos pos) {
        BlockState state = relicheirus.level().getBlockState(pos);
        if (state.isAir() || state.is(ACTagRegistry.UNMOVEABLE)) {
            return false;
        } else {
            return state.is(ACTagRegistry.RELICHEIRUS_KNOCKABLE_LOGS) || state.is(ACTagRegistry.RELICHEIRUS_KNOCKABLE_LEAVES);
        }
    }

public boolean lockTreePosition(BlockPos target) {
        Vec3 vec3 = Vec3.atCenterOf(target).subtract(this.position());
        float f = -((float) Mth.atan2(vec3.x, vec3.z)) * 180.0F / (float) Math.PI;
        BlockState state = level().getBlockState(target);
        Direction dir = Direction.fromYRot(f);
        if (state.is(ACBlockRegistry.PEWEN_BRANCH.get())) {
            dir = Direction.fromYRot(state.getValue(PewenBranchBlock.ROTATION) * 45);
        }
        float targetRot = Mth.approachDegrees(this.getYRot(), dir.toYRot(), 20);
        this.setYRot(targetRot);
        this.setYHeadRot(targetRot);
        this.yBodyRot = targetRot;
        if (level().getBlockState(target.below()).isAir()) {
            target = target.relative(dir);
        }
        Vec3 vec31 = Vec3.atCenterOf(target.relative(dir.getOpposite(), 2));
        Vec3 vec32 = vec31.subtract(this.position());
        if (vec32.length() > 1) {
            vec32 = vec32.normalize();
        }
        Vec3 delta = new Vec3(vec32.x * 0.1F, 0F, vec32.z * 0.1F);
        this.setDeltaMovement(this.getDeltaMovement().add(delta));
        return this.distanceToSqr(vec31.x, this.getY(), vec31.z) < 4.0D && Mth.degreesDifferenceAbs(this.getYRot(), dir.toYRot()) < 7;
    }

public BlockPos getStandAtTreePos(BlockPos target) {
        Vec3 vec3 = Vec3.atCenterOf(target).subtract(this.position());
        float f = -((float) Mth.atan2(vec3.x, vec3.z)) * 180.0F / (float) Math.PI;
        BlockState state = level().getBlockState(target);
        Direction dir = Direction.fromYRot(f);
        if (state.is(ACBlockRegistry.PEWEN_BRANCH.get())) {
            dir = Direction.fromYRot(state.getValue(PewenBranchBlock.ROTATION) * 45);
        }
        if (level().getBlockState(target.below()).isAir()) {
            target = target.relative(dir);
        }
        return target.relative(dir.getOpposite(), 4).atY((int) this.getY());
    }

@Override
    public void tick() {
        if (tickCount % 20 == 0) {
            if (!isDormant || level().isClientSide()
                    || !onGround() || isDeadOrDying()
                    || isPassenger() || !getPassengers().isEmpty()
                    || level().getNearestPlayer(this, 32) != null) {
                tickRate = 1;
            } else {
                tickRate = DORMANT_TICK_RATE;
            }
        }

        if (tickCount % tickRate != 0) {
            return;
        }
        super.tick();

        if (isInWater()) {
            ticksInAir = 0;
        } else if (!onGround()) {
            ticksInAir++;
        } else {
            if (ticksInAir > 0) {
                playSound(getLandingSound(), getSoundVolume(), getVoicePitch());
                ticksInAir = 0;
            }
        }

        if (attackCooldown > 0) {
            attackCooldown--;
        }
    }

public void setDormant(boolean isDormant) {
        this.isDormant = isDormant;
        if (!isDormant) {
            facing = null;
        }
    }

@Override
    public void playerTouch(Player player) {
        if (attackCooldown <= 0
                && player.level().getDifficulty() != Difficulty.PEACEFUL
                && isAlive()
                && isWithinMeleeAttackRange(player)
                && hasLineOfSight(player)
        ) {
            attackCooldown = 20;
            DamageSource damageSource = this.damageSources().mobAttack(this);
            float amount = (float) getAttributeValue(Attributes.ATTACK_DAMAGE);
            if (player.hurtOrSimulate(damageSource, amount) && level() instanceof ServerLevel level) {
                EnchantmentHelper.doPostAttackEffects(level, player, damageSource);
            }
        }
    }

@Override
    public void setTarget(LivingEntity entity) {
        setDormant(false);
        super.setTarget(entity);
    }
